// Generated by the platform from the OpenAPI contract (ADR-0016). Do not edit: it follows the design (C3).

import { call } from './client-runtime'
export { ApiError } from './client-runtime'

export interface CalcularComisionRequest {
  /** decimal(19,4,signed) */
  monto: number
  /** text(var,3,utf8) */
  tipo: string
}

export interface CalcularComisionResponse {
  /** decimal(19,4,signed) */
  comision: number
}

export interface RealizarTransferenciaRequest {
  /** text(var,10,utf8) */
  cuentaOrigen: string
  /** text(var,10,utf8) */
  cuentaDestino: string
  /** decimal(19,4,signed) */
  monto: number
  /** text(var,3,utf8) */
  tipo: string
}

export interface RealizarTransferenciaResponse {
  /** integer(32,signed) */
  status: number
  /** text(var,100,utf8) */
  mensaje: string
  /** text(var,12,utf8) */
  comision: string
  /** integer(32,signed) */
  numero: number
}

export interface ObtenerComprobanteRequest {
  /** integer(32,signed) */
  numero: number
}

export interface ObtenerComprobanteResponse {
  /** text(var,12,utf8) */
  numero: string
  /** text(var,15,utf8) */
  monto: string
}

export interface Api {
  /** Calculates the commission of an operation: flat 0.50 up to 1000.00, otherwise 0.1% rounded half away from zero to 2 decimals, capped at 5.00, plus 1.00 for type INM applied after the cap. (rules RULE-001, RULE-002, RULE-003) */
  calcularComision(request: CalcularComisionRequest): Promise<CalcularComisionResponse>
  /** Transfers between two accounts: rejects same account, validates origin (exists, active) and destination (active), checks that the balance covers amount plus commission, debits amount plus commission from the origin, credits only the amount to the destination, registers the transfer with the next sequential number and commits. Returns the status and the outputs as the legacy does on every path. (rules RULE-005, RULE-006, RULE-007, RULE-008, RULE-009, RULE-010) */
  realizarTransferencia(request: RealizarTransferenciaRequest): Promise<RealizarTransferenciaResponse>
  /** Looks up a transfer by number and returns the number and the stored amount formatted with two decimals; the amount is blank if the transfer does not exist (no error). (rules RULE-004) */
  obtenerComprobante(request: ObtenerComprobanteRequest): Promise<ObtenerComprobanteResponse>
}

/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */
export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init)): Api {
  return {
    calcularComision: (request) => call<CalcularComisionResponse>(fetchImpl, baseUrl, 'POST', '/api/transferencias/comisiones/calculos', request, true),
    realizarTransferencia: (request) => call<RealizarTransferenciaResponse>(fetchImpl, baseUrl, 'POST', '/api/transferencias/transferencias', request, true),
    obtenerComprobante: (request) => call<ObtenerComprobanteResponse>(fetchImpl, baseUrl, 'GET', '/api/transferencias/comprobantes/{numero}', request, false),
  }
}
